"""Split a sequence into n partitions."""


def shard(items, n):
    chunks = [[] for _ in range(n)]
    for i, x in enumerate(items):
        chunks[i % (n - 1 if n > 1 else 1)].append(x)
    return chunks

files.merge.py:
"""Combine partitions back into one sequence."""


def merge(chunks):
    if not chunks:
        return []
    return list(chunks[0])

