files.workshare.py:
"""Split work for parallel workers."""


def split_work(items, n):
    if n <= 0:
        raise ValueError("n must be positive")
    if n == 1:
        return [list(items)]
    return [list(items[i::n]) for i in range(n - 1)]

files.addup.py:
"""Add partial worker results."""


def combine(partials):
    total = 0
    for part in partials:
        total += part
    return total

